
require('dotenv').config()

const express = require('express')
const crypto = require('node:crypto')

const app = express()
const PORT = Number(process.env.PORT || 3001)

app.use(express.json({ limit: '20kb' }))

// Temporary in-memory notification storage
const notifications = []

const authenticateService = (req, res, next) => {
  const expected = process.env.SERVICE_TOKEN
  const provided = req.get('x-service-token') || ''

  if (!expected) {
    return res.status(503).json({
      message: 'Service token is not configured',
    })
  }

  const expectedBuffer = Buffer.from(expected)
  const providedBuffer = Buffer.from(provided)

  if (
    expectedBuffer.length !== providedBuffer.length ||
    !crypto.timingSafeEqual(expectedBuffer, providedBuffer)
  ) {
    return res.status(401).json({
      message: 'Unauthorized',
    })
  }

  next()
}

// Health check
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    service: 'mini-erp-notifications',
  })
})

// Create a low-stock notification
app.post('/notifications/low-stock', authenticateService, (req, res) => {
  const {
    product_id,
    product_name,
    sku,
    stock_quantity,
    reorder_level,
  } = req.body || {}

  const valid =
    Number.isSafeInteger(product_id) &&
    product_id > 0 &&
    typeof product_name === 'string' &&
    product_name.trim().length > 0 &&
    typeof sku === 'string' &&
    sku.trim().length > 0 &&
    Number.isSafeInteger(stock_quantity) &&
    stock_quantity >= 0 &&
    Number.isSafeInteger(reorder_level) &&
    reorder_level >= 0

  if (!valid) {
    return res.status(422).json({
      message: 'Invalid product data',
    })
  }

  if (stock_quantity > reorder_level) {
    return res.status(200).json({
      message: 'Stock is sufficient. No alert created.',
    })
  }

  const notification = {
    id: crypto.randomUUID(),
    type: 'LOW_STOCK',
    product_id,
    product_name,
    sku,
    stock_quantity,
    reorder_level,
    message: `Low stock: ${product_name} has ${stock_quantity} units remaining.`,
    created_at: new Date().toISOString(),
  }

  notifications.unshift(notification)

  console.log('LOW STOCK ALERT:', notification.message)

  return res.status(201).json({
    message: 'Low-stock notification created',
    data: notification,
  })
})

// List notifications (protected)
app.get('/notifications', authenticateService, (req, res) => {
  res.json({
    data: notifications,
    total: notifications.length,
  })
})

app.listen(PORT, '127.0.0.1', () => {
  console.log(`Notification service running on http://127.0.0.1:${PORT}`)
})
